d["convergences"]=[
{"date":"1774-07-17","label":"Presentation at Kew","eyes":["mai","banks"],"note":"The host's record is of a social triumph; Mai's side survives only as a joke about 'King Tosh' told later and a request for gunpowder, which may or may not be his."},
{"date":"1774-12","label":"Dinner at the Burneys'","eyes":["fanny","mai"],"note":"Fanny writes Mai as a model of natural courtesy to shame English gentlemen; the same letter preserves, in her spelling, his English and his own interests, which were not hers."},
{"date":"1776-04","label":"London's last look, spring 1776","eyes":["boswell","reynolds","fanny"],"note":"Within a few weeks Johnson declares him genteel, Reynolds exhibits him as a classical hero, and Fanny reports him criticising a duchess: three uses of one man to say something about the English."},
{"date":"1777-08-12","label":"Arrival at Tahiti","eyes":["gilbert","mai"],"note":"A sister's tears and a crowd drawn by red feathers; a young officer notes how quickly the interest faded."},
{"date":"1777-10-13","label":"Settlement at Huahine","eyes":["cook","mai","samwell"],"note":"Cook records a council and a land grant, Mai's reported plea is for his father's land on Raiatea, and Samwell sees the horse that made him a spectacle."},
{"date":"1777-10-15","label":"Huahine or Raiatea?","eyes":["james-burney","king"],"note":"Burney logs Mai's wavering; King explains it as a single unchanging aim, to drive out the Bora Bora conquerors."},
{"date":"1777-11-02","label":"The farewell","eyes":["cook","king","mai"],"note":"Cook stresses Mai's composure until the last handshake, King his tears all the way to the beach; Mai's own feelings are known only through them."}
]

